// paste-warden-opencode-plugin v1
// PasteWarden guard for opencode 2.x (V2 plugin API: ctx.tool.hook("execute.before")).
// Generated by `paste-warden hook install opencode`; remove with
// `paste-warden hook uninstall opencode`. Do not edit: reinstalling overwrites it.
// The V1 form (a tool.execute.before hook key) is silently ignored by opencode 2.x.
import { Plugin } from "@opencode/plugin"
import { spawnSync } from "node:child_process"

const BIN = __PASTE_WARDEN_BIN__
const TIMEOUT_MS = 10000
const FAILED =
  "PasteWarden 無法完成檢查，為了安全先擋下。請告知使用者。\n" +
  "PasteWarden could not finish its check and blocked the call to stay safe. Tell the user."

export default Plugin.define({
  id: "paste-warden",
  async setup(ctx) {
    await ctx.tool.hook("execute.before", (event) => {
      // Fail closed: any problem running or reading the hook blocks the call.
      let r
      try {
        r = spawnSync(BIN, ["hook", "opencode"], {
          input: JSON.stringify({ tool: String(event.tool), args: event.input ?? {} }),
          encoding: "utf8",
          timeout: TIMEOUT_MS,
          windowsHide: true,
        })
      } catch {
        throw new Error(FAILED)
      }
      let v = null
      try {
        v = JSON.parse(r.stdout)
      } catch {}
      if (r.status !== 0 || v === null || typeof v.block !== "boolean") {
        throw new Error(v && typeof v.reason === "string" && v.reason ? v.reason : FAILED)
      }
      if (v.block) throw new Error(v.reason)
    })
  },
})
